-- Tabela: avaliacoes_desempenho
DROP TABLE IF EXISTS `avaliacoes_desempenho`;
CREATE TABLE `avaliacoes_desempenho` (
  `id` char(36) NOT NULL,
  `nota_tecnica` decimal(4,2),
  `nota_comportamental` decimal(4,2),
  `nota_final` decimal(4,2),
  `classificacao` enum('Excelente','Bom','Suficiente','Insuficiente','Mau'),
  `objectivos` longtext,
  `pontos_fortes` text,
  `pontos_melhoria` text,
  `plano_melhoria` text,
  `feedback_avaliador` text,
  `feedback_avaliado` text,
  `estado` enum('Rascunho','Submetida','Validada','Arquivada') DEFAULT 'Rascunho',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `colaborador_id` char(36),
  `ciclo_id` char(36),
  `avaliador_id` char(36),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- Tabela: avisos
DROP TABLE IF EXISTS `avisos`;
CREATE TABLE `avisos` (
  `id` char(36) NOT NULL,
  `titulo` varchar(200) NOT NULL,
  `conteudo` text NOT NULL,
  `tipo` enum('Geral','Urgente','Informativo','Evento') DEFAULT 'Geral',
  `visivel_para` enum('Todos','Departamento','Cargo','Perfil') DEFAULT 'Todos',
  `departamento_id` char(36),
  `data_inicio` datetime,
  `data_fim` datetime,
  `publicado` tinyint(1) DEFAULT '1',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- Tabela: cargos
DROP TABLE IF EXISTS `cargos`;
CREATE TABLE `cargos` (
  `id` char(36) NOT NULL,
  `nome` varchar(150) NOT NULL,
  `codigo` varchar(20),
  `descricao` text,
  `categoria` varchar(100),
  `nivel_minimo` int(11) DEFAULT '1',
  `salario_minimo` decimal(12,2),
  `salario_maximo` decimal(12,2),
  `activo` tinyint(1) DEFAULT '1',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- Tabela: ciclos_avaliacao
DROP TABLE IF EXISTS `ciclos_avaliacao`;
CREATE TABLE `ciclos_avaliacao` (
  `id` char(36) NOT NULL,
  `nome` varchar(150) NOT NULL,
  `descricao` text,
  `data_inicio` date NOT NULL,
  `data_fim` date NOT NULL,
  `estado` enum('Planeado','Em_curso','Concluido','Cancelado') DEFAULT 'Planeado',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- Tabela: colaboradores
DROP TABLE IF EXISTS `colaboradores`;
CREATE TABLE `colaboradores` (
  `id` char(36) NOT NULL,
  `numero_colaborador` varchar(20) NOT NULL,
  `nome_completo` varchar(200),
  `nome_curto` varchar(100),
  `data_nascimento` date,
  `genero` enum('M','F','Outro'),
  `estado_civil` enum('Solteiro(a)','Casado(a)','Divorciado(a)','Viúvo(a)','União de Facto'),
  `nif` varchar(20),
  `bi` varchar(30),
  `bi_validade` date,
  `email_pessoal` varchar(150),
  `email_institucional` varchar(150),
  `telefone` varchar(20),
  `telefone_emergencia` varchar(20),
  `endereco` text,
  `cidade` varchar(100),
  `provincia` varchar(100),
  `fotografia` varchar(500),
  `numero_seguranca_social` varchar(30),
  `conta_bancaria` varchar(30),
  `banco` varchar(100),
  `iban` varchar(30),
  `habilitacoes` varchar(200),
  `formacao_academica` text,
  `curriculo` varchar(500),
  `tipo_colaborador` enum('Interno','Externo','Formador_Interno','Formador_Externo','Estagiario') DEFAULT 'Interno',
  `estado` enum('Activo','Inactivo','Suspenso','Aposentado','Desligado') DEFAULT 'Activo',
  `data_admissao` date NOT NULL,
  `data_desligamento` date,
  `motivo_desligamento` text,
  `observacoes` text,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `organizacao_id` char(36),
  `utilizador_id` char(36),
  `departamento_id` char(36),
  `cargo_id` char(36),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

