-- Tabela: contratos
DROP TABLE IF EXISTS `contratos`;
CREATE TABLE `contratos` (
  `id` char(36) NOT NULL,
  `numero` varchar(30) NOT NULL,
  `tipo` enum('Determinado','Indeterminado','Prestacao_Servicos','Estagio','Temporario') DEFAULT 'Indeterminado',
  `data_inicio` date NOT NULL,
  `data_fim` date,
  `data_assinatura` date,
  `salario_base` decimal(12,2) NOT NULL,
  `moeda` varchar(3) DEFAULT 'AOA',
  `periodo_experimentacao` int(11),
  `funcao` varchar(150),
  `local_trabalho` varchar(200),
  `horario_trabalho` varchar(100),
  `estado` enum('Activo','Suspenso','Rescindido','Expirado','Renovado') DEFAULT 'Activo',
  `motivo_rescisao` text,
  `data_rescisao` date,
  `observacoes` text,
  `documento` varchar(500),
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `colaborador_id` char(36),
  `subsidio_alimentacao` decimal(12,2),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

