-- Tabela: cursos_formacao
DROP TABLE IF EXISTS `cursos_formacao`;
CREATE TABLE `cursos_formacao` (
  `id` char(36) NOT NULL,
  `nome` varchar(200) NOT NULL,
  `descricao` text,
  `categoria` varchar(100),
  `tipo` enum('Interno','Externo','Online','Seminario','Workshop') DEFAULT 'Interno',
  `horas` int(11),
  `data_inicio` date,
  `data_fim` date,
  `vagas` int(11),
  `local` varchar(200),
  `estado` enum('Planeado','Em_curso','Concluido','Cancelado') DEFAULT 'Planeado',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- Tabela: departamentos
DROP TABLE IF EXISTS `departamentos`;
CREATE TABLE `departamentos` (
  `id` char(36) NOT NULL,
  `nome` varchar(150) NOT NULL,
  `codigo` varchar(20),
  `descricao` text,
  `tipo` enum('Direccao','Departamento','Sector','Seccao','Gabinete') DEFAULT 'Departamento',
  `responsavel_nome` varchar(200),
  `telefone` varchar(20),
  `email` varchar(150),
  `localizacao` varchar(200),
  `activo` tinyint(1) DEFAULT '1',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `departamento_pai_id` char(36),
  `organizacao_id` char(36),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

INSERT INTO `departamentos` (`id`, `nome`, `codigo`, `descricao`, `tipo`, `responsavel_nome`, `telefone`, `email`, `localizacao`, `activo`, `createdAt`, `updatedAt`, `departamento_pai_id`, `organizacao_id`) VALUES ('3d15b573-4010-4260-a32b-1c34cbb7f3c0', 'PRODUÇÃO', 'KOAG3', 'O Departamento de Produção é o setor responsável por transformar os pedidos dos clientes em produtos gráficos acabados, assegurando que cada trabalho seja executado com qualidade, dentro do prazo estabelecido, ao menor custo possível e de acordo com as especificações técnicas.\n\nÉ o núcleo operacional da oficina gráfica, coordenando todas as etapas da produção, desde o recebimento da Ordem de Produção até à entrega do material acabado ao cliente.', 'Departamento', 'Lucas Rodrigues', '930329103', '', 'Rua 22 de janeiro, junto ao Siac, Cacuaco, Icole e Bengo', 1, '2026-07-31 08:50:22', '2026-07-31 08:50:22', NULL, '5002ed17-b1c3-414d-9a5a-d364482c1342');
INSERT INTO `departamentos` (`id`, `nome`, `codigo`, `descricao`, `tipo`, `responsavel_nome`, `telefone`, `email`, `localizacao`, `activo`, `createdAt`, `updatedAt`, `departamento_pai_id`, `organizacao_id`) VALUES ('6c15bf23-b85d-4e89-b9f2-0890aa4c59e1', 'HIGIENE E MANUTENÇÃO', 'KOAG5', 'O Departamento de Higiene e Manutenção é responsável por assegurar a limpeza, conservação, manutenção preventiva e corretiva das instalações, máquinas, equipamentos e infraestruturas da oficina de artes gráficas. O seu principal objetivo é garantir um ambiente de trabalho limpo, seguro, funcional e adequado ao desenvolvimento das atividades produtivas.\n\nEste departamento desempenha um papel fundamental na continuidade da produção, reduzindo paragens de equipamentos, prolongando a vida útil dos ativos e promovendo condições adequadas de higiene, segurança e saúde ocupacional.', 'Departamento', 'Rodé Mualufula', '944370415', '', 'Rua 22 de janeiro, junto ao Siac, Cacuaco, Icole e Bengo', 1, '2026-07-31 08:58:16', '2026-07-31 09:31:45', NULL, '5002ed17-b1c3-414d-9a5a-d364482c1342');
INSERT INTO `departamentos` (`id`, `nome`, `codigo`, `descricao`, `tipo`, `responsavel_nome`, `telefone`, `email`, `localizacao`, `activo`, `createdAt`, `updatedAt`, `departamento_pai_id`, `organizacao_id`) VALUES ('89a60138-57f9-4127-9962-4f2c5c4d69e4', 'ADMINISTRAÇÃO E FINANÇAS', 'KOAG1', 'O Departamento de Administração e Finanças é a unidade responsável pela gestão administrativa, financeira, contabilística e patrimonial da gráfica. Tem como principal missão garantir a sustentabilidade financeira da empresa, assegurar o cumprimento das obrigações legais e fiscais, controlar os recursos financeiros e fornecer informações confiáveis para apoiar a tomada de decisões da direção. \n\nEste departamento atua como um centro de suporte estratégico, coordenando o planeamento financeiro, a execução do orçamento, o controlo de custos, a gestão do caixa, as compras, os pagamentos, o património e a documentação administrativa, assegurando que todas as operações da gráfica decorram de forma organizada, transparente e eficiente. Incluí as áreas seguintes: Área administrativa, Financeira, Contabilística, Compras, Custos e Serviços', 'Departamento', 'Gabriel Mbangui', '923857862', '', 'Rua 22 de janeiro, junto ao Siac, Cacuaco, Icole e Bengo', 1, '2026-07-31 08:19:55', '2026-07-31 08:46:56', NULL, '5002ed17-b1c3-414d-9a5a-d364482c1342');
INSERT INTO `departamentos` (`id`, `nome`, `codigo`, `descricao`, `tipo`, `responsavel_nome`, `telefone`, `email`, `localizacao`, `activo`, `createdAt`, `updatedAt`, `departamento_pai_id`, `organizacao_id`) VALUES ('9e2624a6-2549-4a1a-b74d-bdfb88c4cbf6', 'COORDENAÇÃO PEDAGOGICA', 'KAT1', '', 'Departamento', 'COSTA RODRIGUES', '929190854', '', 'Rua 22 de janeiro, junto ao Siac, Cacuaco, Icole e Bengo', 1, '2026-08-17 12:09:44', '2026-08-18 10:19:29', NULL, '5002ed17-b1c3-414d-9a5a-d364482c1342');
INSERT INTO `departamentos` (`id`, `nome`, `codigo`, `descricao`, `tipo`, `responsavel_nome`, `telefone`, `email`, `localizacao`, `activo`, `createdAt`, `updatedAt`, `departamento_pai_id`, `organizacao_id`) VALUES ('a6979245-901c-498c-a600-d15686297eee', 'COODERNAÇÃO EXECUTIVA', 'KAE2', '', 'Departamento', 'COSTA RODRIGUES', '929190854', '', 'Rua 22 de janeiro, junto ao Siac, Cacuaco, Icole e Bengo', 1, '2026-08-17 12:10:53', '2026-08-18 10:18:59', NULL, '5002ed17-b1c3-414d-9a5a-d364482c1342');
INSERT INTO `departamentos` (`id`, `nome`, `codigo`, `descricao`, `tipo`, `responsavel_nome`, `telefone`, `email`, `localizacao`, `activo`, `createdAt`, `updatedAt`, `departamento_pai_id`, `organizacao_id`) VALUES ('cc00049d-53c7-4430-a01d-7ec8d637390a', 'COMERCIAL', 'KOAG2', 'O Departamento Comercial de uma Oficina de Artes Gráficas é responsável por captar clientes, vender serviços gráficos, gerir o relacionamento comercial e acompanhar todo o processo desde o primeiro contacto até à entrega do trabalho. É o elo entre o cliente e os departamentos de produção.', 'Departamento', 'Esperança Gonga', '944471642', '', 'Rua 22 de janeiro, junto ao Siac, Cacuaco, Icole e Bengo', 1, '2026-07-31 08:45:40', '2026-07-31 08:51:02', NULL, '5002ed17-b1c3-414d-9a5a-d364482c1342');
INSERT INTO `departamentos` (`id`, `nome`, `codigo`, `descricao`, `tipo`, `responsavel_nome`, `telefone`, `email`, `localizacao`, `activo`, `createdAt`, `updatedAt`, `departamento_pai_id`, `organizacao_id`) VALUES ('f8a10c00-19eb-41be-92b1-e3535e10b102', 'SEGURANÇA', 'KOAG4', 'O Departamento de Segurança é responsável por garantir a segurança física das pessoas, das instalações, dos equipamentos, dos materiais e das informações da oficina de artes gráficas. Atua na prevenção de acidentes de trabalho, incêndios, furtos, acessos não autorizados e outros riscos que possam comprometer a continuidade das operações.\n\nAlém da segurança patrimonial, o departamento promove a Segurança e Saúde no Trabalho (SST), assegurando que todas as atividades sejam realizadas em conformidade com as normas de segurança, higiene e proteção ambiental.', 'Departamento', 'Paulo Cassoma', '923505877', '', 'Rua 22 de janeiro, junto ao Siac, Cacuaco, Icole e Bengo', 1, '2026-07-31 08:55:20', '2026-07-31 08:55:20', NULL, '5002ed17-b1c3-414d-9a5a-d364482c1342');

-- Tabela: ferias
DROP TABLE IF EXISTS `ferias`;
CREATE TABLE `ferias` (
  `id` char(36) NOT NULL,
  `ano` int(11) NOT NULL,
  `dias_totais` int(11) DEFAULT '22',
  `dias_gozados` int(11) DEFAULT '0',
  `dias_restantes` int(11) DEFAULT '22',
  `estado` enum('Pendente','Aprovado','Rejeitado','Gozado','Cancelado') DEFAULT 'Pendente',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `colaborador_id` char(36),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- Tabela: inscricoes_formacao
DROP TABLE IF EXISTS `inscricoes_formacao`;
CREATE TABLE `inscricoes_formacao` (
  `id` char(36) NOT NULL,
  `data_inscricao` date,
  `estado` enum('Inscrito','Concluido','Abandonou','Certificado') DEFAULT 'Inscrito',
  `nota_avaliacao` decimal(4,2),
  `horas_realizadas` int(11),
  `certificado` tinyint(1) DEFAULT '0',
  `data_certificado` date,
  `observacoes` text,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `colaborador_id` char(36),
  `curso_id` char(36),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- Tabela: licencas
DROP TABLE IF EXISTS `licencas`;
CREATE TABLE `licencas` (
  `id` char(36) NOT NULL,
  `tipo` enum('Medica','Maternidade','Paternidade','Casamento','Falecimento','Formacao','Sem_Vencimento','Outra') NOT NULL,
  `data_inicio` date NOT NULL,
  `data_fim` date,
  `dias` int(11) NOT NULL,
  `motivo` text,
  `documento` varchar(500),
  `estado` enum('Pendente','Aprovada','Rejeitada','Em_curso','Concluida') DEFAULT 'Pendente',
  `aprovado_por` char(36),
  `observacoes` text,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `colaborador_id` char(36),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- Tabela: logs_auditoria
DROP TABLE IF EXISTS `logs_auditoria`;
CREATE TABLE `logs_auditoria` (
  `id` char(36) NOT NULL,
  `utilizador_id` char(36),
  `accao` varchar(50) NOT NULL,
  `modulo` varchar(50) NOT NULL,
  `entidade` varchar(100),
  `entidade_id` char(36),
  `dados_antes` longtext,
  `dados_depois` longtext,
  `ip_address` varchar(45),
  `user_agent` text,
  `descricao` text,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- Tabela: notificacoes
DROP TABLE IF EXISTS `notificacoes`;
CREATE TABLE `notificacoes` (
  `id` char(36) NOT NULL,
  `titulo` varchar(200) NOT NULL,
  `mensagem` text NOT NULL,
  `tipo` enum('info','warning','success','error') DEFAULT 'info',
  `lida` tinyint(1) DEFAULT '0',
  `link` varchar(500),
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `utilizador_id` char(36),
  `organizacao_id` char(36) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

