-- Tabela: registos_presenca
DROP TABLE IF EXISTS `registos_presenca`;
CREATE TABLE `registos_presenca` (
  `id` char(36) NOT NULL,
  `data` date NOT NULL,
  `hora_entrada` time,
  `hora_saida` time,
  `horas_trabalhadas` decimal(5,2),
  `horas_extras` decimal(5,2) DEFAULT '0.00',
  `estado` enum('Presente','Ausente','Atrasado','Licenca','Ferias','Fim_semana') DEFAULT 'Presente',
  `metodo` enum('Manual','Biometrico','GPS','QR_Code') DEFAULT 'Manual',
  `observacoes` text,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `colaborador_id` char(36),
  `turno_id` char(36),
  `justificado` tinyint(1) NOT NULL DEFAULT '0',
  `documento_justificacao` varchar(500),
  `justificacao_observacoes` text,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

