-- Tabela: solicitacoes_ferias
DROP TABLE IF EXISTS `solicitacoes_ferias`;
CREATE TABLE `solicitacoes_ferias` (
  `id` char(36) NOT NULL,
  `data_inicio` date NOT NULL,
  `data_fim` date NOT NULL,
  `dias_solicitados` int(11) NOT NULL,
  `motivo` text,
  `estado` enum('Pendente','Aprovado','Rejeitado','Cancelado') DEFAULT 'Pendente',
  `aprovado_por` char(36),
  `data_aprovacao` datetime,
  `observacoes_aprovacao` text,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `colaborador_id` char(36),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- Tabela: turnos
DROP TABLE IF EXISTS `turnos`;
CREATE TABLE `turnos` (
  `id` char(36) NOT NULL,
  `nome` varchar(100) NOT NULL,
  `hora_inicio` time NOT NULL,
  `hora_fim` time NOT NULL,
  `dias_semana` longtext NOT NULL,
  `flexivel` tinyint(1) DEFAULT '0',
  `activo` tinyint(1) DEFAULT '1',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- Tabela: utilizadores
