-- Tabela: vencimentos
DROP TABLE IF EXISTS `vencimentos`;
CREATE TABLE `vencimentos` (
  `id` char(36) NOT NULL,
  `salario_base` decimal(12,2) NOT NULL,
  `subsidio_alimentacao` decimal(12,2) DEFAULT '0.00',
